sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform shader blurred;
uniform float4 screen;
uniform float blur;
uniform float feather;
uniform float saturation;
uniform float brightness;
uniform float gamma;
uniform float fgAlpha;
uniform float bgAlpha;
layout(color) uniform half4 tintColor;
uniform float tint;
layout(color) uniform half4 edgeColor;
uniform float edgeStrength;
uniform float scanStrength;
uniform float scanCount;
uniform float2 fgOffset;
uniform float fgScale;
uniform float2 bgOffset;
uniform float bgScale;
float luma(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }
half4 main(float2 coord) {
    float2 c = size * 0.5;
    float margin = max(blur, 0.0) * 0.5;
    float2 inner = max(size - 2.0 * margin, float2(1.0));
    float k = max(screen.z / inner.x, screen.w / inner.y) * max(bgScale, 0.01);
    half4 b = blurred.eval(c + (coord - screen.xy - screen.zw * 0.5 - bgOffset) / k);
    float3 rgb = b.a > 0.0 ? float3(b.rgb) / float(b.a) : float3(0.0);
    rgb = clamp(mix(float3(luma(rgb)), rgb, 1.0 + saturation), 0.0, 1.0);
    float l = luma(rgb);
    if (l > 0.0) rgb *= pow(l, 1.0 / max(gamma, 0.01)) / l;
    rgb = brightness < 0.0 ? rgb * (1.0 + brightness) : mix(rgb, float3(1.0), brightness);
    float3 hue = float3(tintColor.rgb) * luma(rgb) / max(luma(float3(tintColor.rgb)), 0.001);
    rgb = mix(rgb, hue, clamp(tint, 0.0, 1.0));
    if (scanStrength > 0.0 && fract((coord.y - screen.y) / screen.w * scanCount) > 0.5) rgb *= 1.0 - clamp(scanStrength, 0.0, 1.0);
    half4 bg = half4(half3(clamp(rgb, 0.0, 1.0)), 1.0) * half(float(b.a) * clamp(bgAlpha, 0.0, 1.0));
    float2 fp = c + (coord - c - fgOffset) / max(fgScale, 0.01);
    half4 fg = image.eval(fp);
    float soft = float(blurred.eval(fp).a);
    float spread = blur > 0.0 ? 1.0 : 0.0;
    fg *= half(mix(1.0, smoothstep(0.5, 1.0, soft), clamp(feather, 0.0, 1.0) * spread) * clamp(fgAlpha, 0.0, 1.0));
    float e = clamp(soft * 2.0, 0.0, 1.0) * clamp(edgeStrength, 0.0, 1.0) * float(edgeColor.a) * spread;
    half4 under = half4(edgeColor.rgb * half(e), half(e)) + bg * half(1.0 - e);
    return fg + under * (1.0 - fg.a);
}
